Definition is_end (j : nat) : bool := existsb (fun r : nat * nat * nat * Z => let '(j', _, _, p) := r in (Nat.eqb j' j && Z.eqb p AFTERV)%bool) G.RETS.
Definition is_vis (pc : Z) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$pc;R+F!2'_0!2'_1#1'_2!2'_1#1'_3").
Definition is_vret (j : nat) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S30!2+E+G+G!2+E0+G!2+E1+F$j;R+G!3'_42$r;R2-ERN$r;R!2+E1+F+^9#11$p0;R1$p;R+F-ERN$p0;R!2+E0+G+^9#21$p1;R0$n;R+G-ERN$p1;R!2+E+G+G+^9#21$j';R+G$n0;R+G!2'_5!2'_6#2#8!1'_7#5'_8").
Definition SEND0 : expr := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10}V!2'_9!1,10!1,1}W").
Definition SCEND0 : expr := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10}V!2'_9!1,10!1,1}X").
(* [comment removed for export] *)
Definition view_chk (cells : list kentry) : bool :=
  match SPA.pview_w cells Pb PE CE with
  | Some pv => (expr_eqb (PB4.pv_level pv) (EVar 41) && expr_eqb (PB4.pv_wend pv) (EVar 33) && expr_eqb (PB4.pv_wptr pv) (EVar 32) && expr_eqb (PB4.pv_st pv) (ELit 17)
                && expr_eqb (PB4.pv_sst pv) (EVar 43) && expr_eqb (PB4.pv_nst pv) (EVar 44) && expr_eqb (PB4.pv_more pv) (ELit 1) && expr_eqb (PB4.pv_done pv) (EVar 46)
                && expr_eqb (PB4.pv_size pv) (EVar 36) && expr_eqb (PB4.pv_sb pv) (EVar 38) && expr_eqb (PB4.pv_send pv) SEND0 && expr_eqb (PB4.pv_scend pv) SCEND0)%bool
  | None => false
  end.
Definition nxg2 (cj : CC.cutpoint) : nat := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$cj;R+_:!2'_;!2'_;!1'_<#1'_=}2").
(* [comment removed for export] *)
Definition jof (pc : Z) : nat := match find (fun r : nat * nat * nat * Z => let '(_, _, _, p) := r in Z.eqb p pc) G.RETS with Some (j, _, _, _) => j | None => 0%nat end.
Definition JDEC : nat := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00}1").
Definition A1N : nat := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00}^?").
Definition A1V : expr := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!1,1'_>").        (* [comment removed for export] *)
Definition decstr_chk (c : CC.cutpoint) (ps : SR.post_spec) (cj : CC.cutpoint) (BLi BLj : CA.blocks) : option CH2.cinfo :=
  let regs := CA.ps_reglist ps in
  let '(vb, vk) := split_lit (nth 12 regs (ELit 0)) in
  if (expr_eqb (nth 10 regs (ELit 0)) PE && expr_eqb (nth 11 regs (ELit 0)) (EVar 36) && expr_eqb vb (EVar 2) && CH2.blocks_eqb BLj BLi)%bool
  then match CH2.custom_chk GT.NF G.HDECL DSCR 2 BLi [(EVar 2, vk, ELit 8); (ELit 0, ERRNO, ELit 4)] (SSU2.decu64_news (EVar 2) vk (nxg2 cj)) (Some (EVar (nxg2 cj))) c ps cj BLi with
       | Some ci => if (Z.leb (CH2.ci_csp ci) vk && Z.leb (vk + 8) 0 && Z.leb (- SCR) vk && Nat.eqb (CC.cp_nx cj) (CH2.ci_nx ci + 2 + APC.NCS) && Nat.leb GT.NF (CH2.ci_nx ci)
                        && Nat.eqb A1N (SSU2.a1var (CH2.ci_nx ci) 2))%bool then Some ci else None
       | None => None end
  else None.
Definition vk_of (ps : SR.post_spec) : Z := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$ps;R+_?!3'_@+_A+F!1'_B!4'_C+_A}<!1'_D#1!1,J,H").
(* [comment removed for export] *)
Definition is_oth (i : nat) : bool := (negb (Nat.eqb i 0) && negb (Nat.eqb i JDEC) && negb (is_end i) && negb (is_vret i))%bool.
Definition stack_reg_eqb (r : SGP.region) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S10!2+E+_A+F$r;R'_E-ERN$r;R!2+E0+_A+^9#11$p;R0$len;R+_A-ERN$p;R!2+E+_A+F+^9#21$b;R+_A$lo;R+F!2'_5!2'_5!2'_F#2!1,1}2!2'_1#1!1'_G'C!2'_F#3!1,J'C").
Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  let cells := SR.ps_cells ps in
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      if Z.eqb pc SETEC then (Nat.eqb i JDEC && SPW.ne_chk cells A1V 0 34 0 && SPW.ne_chk cells A1V 0 34 34)%bool
      else if (Z.eqb pc DECSTR || Z.eqb pc AFTERV)%bool then
        (Z.eqb (SR.ps_pc ps) pc && negb (is_end i) &&
         match CH2.ret_of G.RETS i k with
         | Some j => match nth_error G.CPS j with
                     | Some cj => let BLi := nth i G.BLS [] in let BLj := nth j G.BLS [] in
                                  if Z.eqb pc DECSTR then (Nat.eqb i 0 && Nat.eqb j JDEC && match decstr_chk c ps cj BLi BLj with Some _ => true | None => false end)%bool
                                  else (is_vret i && is_end j && CH2.blocks_eqb BLi SPT.BL0 && expr_eqb (nth 10 (CA.ps_reglist ps) (ELit 0)) Pb && expr_eqb (nth 11 (CA.ps_reglist ps) (ELit 0)) Eb && view_chk cells && PB.has cells (KWord (SA Eb 0) 4 (ELit 0)) && PB.has cells (KWord (SA Vb 0) 8 (ELit PML.VT_VISITOR))
                                        && match PB2.ptrans_chk GT.NF G.HDECL Eb 0 Pb 0 512 11 c ps cj BLi BLj with Some ci => Z.eqb (CH2.ci_csp ci) CSP | None => false end)%bool
                     | None => false end
         | None => false end)%bool
      else if is_vis pc then     (* [comment removed for export] *)
        if Nat.eqb i 0 then (Z.eqb pc VSTR && SPW.rng_in cells (EVar 36) 0 0)%bool
        else (Z.eqb (SR.ps_pc ps) pc && negb (is_end i) && negb (is_vret i) && CH2.blocks_eqb (nth i G.BLS []) SPT.BL0 &&
              (negb (Z.eqb pc VSTR) || (expr_eqb (nth 11 (CA.ps_reglist ps) (ELit 0)) (APC.eaddz (EVar 2) SVOFF) && expr_eqb (nth 12 (CA.ps_reglist ps) (ELit 0)) (ELit 3) &&
                                         PB.has cells (KWord (SA (EVar 2) SVOFF) 8 PE) && PB.has cells (KWord (SA (EVar 2) (SVOFF + 8)) 8 (EVar 36)))) &&
              match CH2.ret_of G.RETS i k with
              | Some j => match nth_error G.CPS j with
                          | Some cj => (is_vret j && negb (is_end j) && CH2.blocks_eqb (nth j G.BLS []) SPT.BL0 &&
                                        match VBX.vis_chk GT.NF G.HDECL Vb c ps cj (nth i G.BLS []) (nth j G.BLS []) with Some ci => Z.leb (CH2.ci_csp ci) SVOFF | None => false end)%bool
                          | None => false end
              | None => false end)%bool
      else (is_oth i || (is_end i && PB.exit_base_chk GT.NF pc c ps && existsb (Z.eqb pc) GT.ENDS && forallb stack_reg_eqb (CC.cp_F c)))%bool
  end.
