  (pc = VSTR -> expr_eqb (nth 11 (CA.ps_reglist ps1) (ELit 0)) (APC.eaddz (EVar 2) SVOFF) = true /\ expr_eqb (nth 12 (CA.ps_reglist ps1) (ELit 0)) (ELit 3) = true /\
                PB.has (SR.ps_cells ps1) (KWord (SA (EVar 2) SVOFF) 8 PE) = true /\ PB.has (SR.ps_cells ps1) (KWord (SA (EVar 2) (SVOFF + 8)) 8 (EVar 36)) = true) ->
